  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_ben,1,'character','Es ist schon spät, aber unser Zug fährt gleich ab.','دیر شده، اما قطارمان به‌زودی حرکت می‌کند.',51,NULL,NULL,NULL,NULL,'[{"lemma":"es","partOfSpeech":"pronoun","surface":"Es","translation":"آن / این / ضمیر خنثی"},{"lemma":"sein","partOfSpeech":"verb","surface":"ist","translation":"بودن"},{"lemma":"schon","partOfSpeech":"adverb","surface":"schon","translation":"قبلا / تا حالا"},{"lemma":"spät","partOfSpeech":"adjective","suffix":",","surface":"spät","translation":"دیر"},{"lemma":"aber","partOfSpeech":"conjunction","surface":"aber","translation":"اما"},{"lemma":"unser","partOfSpeech":"determiner","surface":"unser","translation":"مال ما / ما"},{"lemma":"Zug","partOfSpeech":"noun","surface":"Zug","translation":"قطار"},{"lemma":"fahren","partOfSpeech":"verb","surface":"fährt","translation":"رفتن با وسیله / راندن"},{"lemma":"gleich","partOfSpeech":"adverb","surface":"gleich","translation":"همین الان"},{"lemma":"ab","partOfSpeech":"particle","suffix":".","surface":"ab","translation":"جدا / ارسال"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_1=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_lena,2,'learner','Obwohl es spät ist, fahren wir weiter.','با اینکه دیر است، به مسیر ادامه می‌دهیم.',51,NULL,NULL,'obwohl es spät ist fahren wir weiter',NULL,'[{"lemma":"obwohl","partOfSpeech":"conjunction","surface":"Obwohl","translation":"با اینکه"},{"lemma":"es","partOfSpeech":"pronoun","surface":"es","translation":"آن / این / ضمیر خنثی"},{"lemma":"spät","partOfSpeech":"adjective","surface":"spät","translation":"دیر"},{"lemma":"sein","partOfSpeech":"verb","suffix":",","surface":"ist","translation":"بودن"},{"lemma":"fahren","partOfSpeech":"verb","surface":"fahren","translation":"رفتن با وسیله / راندن"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"weiter","partOfSpeech":"adverb","suffix":".","surface":"weiter","translation":"ادامه / بیشتر"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_2=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_ben,3,'character','Die Fahrt nach Frankfurt dauert ungefähr zwei Stunden.','سفر تا فرانکفورت حدود دو ساعت طول می‌کشد.',51,NULL,NULL,NULL,NULL,'[{"lemma":"der","partOfSpeech":"article","surface":"Die","translation":"حرف تعریف"},{"lemma":"Fahrt","partOfSpeech":"noun","surface":"Fahrt","translation":"سفر / مسیر"},{"lemma":"nach","partOfSpeech":"preposition","surface":"nach","translation":"پس از / به"},{"lemma":"Frankfurt","partOfSpeech":"noun","surface":"Frankfurt","translation":"فرانکفورت"},{"lemma":"dauern","partOfSpeech":"verb","surface":"dauert","translation":"طول کشیدن"},{"lemma":"ungefähr","partOfSpeech":"adverb","surface":"ungefähr","translation":"حدود / تقریباً"},{"lemma":"zwei","partOfSpeech":"number","surface":"zwei","translation":"دو"},{"lemma":"Stunde","partOfSpeech":"noun","suffix":".","surface":"Stunden","translation":"ساعت / یک ساعت"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_3=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_lena,4,'learner','Trotzdem ist diese Verbindung besser als langes Warten.','با این حال این مسیر از انتظار طولانی بهتر است.',51,NULL,NULL,'trotzdem ist diese verbindung besser als langes warten',NULL,'[{"lemma":"trotzdem","partOfSpeech":"adverb","surface":"Trotzdem","translation":"با این حال"},{"lemma":"sein","partOfSpeech":"verb","surface":"ist","translation":"بودن"},{"lemma":"dieser","partOfSpeech":"determiner","surface":"diese","translation":"این"},{"lemma":"Verbindung","partOfSpeech":"noun","surface":"Verbindung","translation":"مسیر / ارتباط"},{"lemma":"gut","partOfSpeech":"adjective","surface":"besser","translation":"خوب"},{"lemma":"als","partOfSpeech":"conjunction","surface":"als","translation":"از / نسبت به"},{"lemma":"lang","partOfSpeech":"adjective","surface":"langes","translation":"طولانی / بلند"},{"lemma":"warten","partOfSpeech":"verb","suffix":".","surface":"Warten","translation":"منتظر ماندن / صبر کردن"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_4=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_ben,5,'character','Wir finden im Zug bestimmt einen freien Platz.','احتمالاً در قطار یک جای خالی پیدا می‌کنیم.',51,NULL,NULL,NULL,NULL,'[{"lemma":"wir","partOfSpeech":"pronoun","surface":"Wir","translation":"ما"},{"lemma":"finden","partOfSpeech":"verb","surface":"finden","translation":"پیدا کردن"},{"lemma":"in","partOfSpeech":"preposition","surface":"im","translation":"در / داخل"},{"lemma":"Zug","partOfSpeech":"noun","surface":"Zug","translation":"قطار"},{"lemma":"bestimmt","partOfSpeech":"adverb","surface":"bestimmt","translation":"حتماً / احتمالاً"},{"lemma":"ein","partOfSpeech":"article","surface":"einen","translation":"یک / حرف تعریف نامعین"},{"lemma":"frei","partOfSpeech":"adjective","surface":"freien","translation":"خالی / آزاد"},{"lemma":"Platz","partOfSpeech":"noun","suffix":".","surface":"Platz","translation":"جا / فضا"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_5=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_lena,6,'learner','Dann steigen wir jetzt ein.','پس همین حالا سوار می‌شویم.',51,NULL,NULL,'dann steigen wir jetzt ein',NULL,'[{"lemma":"dann","partOfSpeech":"adverb","surface":"Dann","translation":"بعد / سپس"},{"lemma":"einsteigen","partOfSpeech":"verb","surface":"steigen","translation":"سوار شدن"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"jetzt","partOfSpeech":"adverb","surface":"jetzt","translation":"حالا / اکنون"},{"lemma":"einsteigen","partOfSpeech":"verb","suffix":".","surface":"ein","translation":"سوار شدن"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
