  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_ben,v_c_lena,'Unterwegs im Zug','در راه داخل قطار','Die Freunde beobachten die Verspätung und bleiben trotz Müdigkeit aufmerksam.','دو دوست تاخیر را دنبال می‌کنند و با وجود خستگی هوشیار می‌مانند.','story','lena-ben-b1-travel-problems',10,51,175,2,'validated','{"relationship":"friends","context":"late-travel","cefr":"B1","storyArc":"continue-despite-obstacles"}');
