  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_ben,1,'character','Der Zug ist ruhig, obwohl viele Reisende unterwegs sind.','قطار آرام است، با اینکه مسافران زیادی در راه هستند.',51,NULL,NULL,NULL,NULL,'[{"lemma":"der","partOfSpeech":"article","surface":"Der","translation":"حرف تعریف"},{"lemma":"Zug","partOfSpeech":"noun","surface":"Zug","translation":"قطار"},{"lemma":"sein","partOfSpeech":"verb","surface":"ist","translation":"بودن"},{"lemma":"ruhig","partOfSpeech":"adjective","suffix":",","surface":"ruhig","translation":"آرام"},{"lemma":"obwohl","partOfSpeech":"conjunction","surface":"obwohl","translation":"با اینکه"},{"lemma":"viel","partOfSpeech":"determiner","surface":"viele","translation":"زیاد / مقدار زیاد"},{"lemma":"Reisende","partOfSpeech":"noun","surface":"Reisende","translation":"مسافر"},{"lemma":"unterwegs","partOfSpeech":"adverb","surface":"unterwegs","translation":"در راه"},{"lemma":"sein","partOfSpeech":"verb","suffix":".","surface":"sind","translation":"بودن"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_7=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_lena,2,'learner','Obwohl wir müde sind, bleiben wir aufmerksam.','با اینکه خسته‌ایم، هوشیار می‌مانیم.',51,NULL,NULL,'obwohl wir müde sind bleiben wir aufmerksam',NULL,'[{"lemma":"obwohl","partOfSpeech":"conjunction","surface":"Obwohl","translation":"با اینکه"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"müde","partOfSpeech":"adjective","surface":"müde","translation":"خسته"},{"lemma":"sein","partOfSpeech":"verb","suffix":",","surface":"sind","translation":"بودن"},{"lemma":"bleiben","partOfSpeech":"verb","surface":"bleiben","translation":"ماندن"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"aufmerksam","partOfSpeech":"adjective","suffix":".","surface":"aufmerksam","translation":"هوشیار / دقیق"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_8=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_ben,3,'character','Auf der Anzeige steht, dass wir zehn Minuten Verspätung haben.','روی تابلو نوشته شده که ده دقیقه تاخیر داریم.',51,NULL,NULL,NULL,NULL,'[{"lemma":"auf","partOfSpeech":"preposition","surface":"Auf","translation":"روی / برای"},{"lemma":"der","partOfSpeech":"article","surface":"der","translation":"حرف تعریف"},{"lemma":"Anzeige","partOfSpeech":"noun","surface":"Anzeige","translation":"تابلو / نمایشگر"},{"lemma":"stehen","partOfSpeech":"verb","suffix":",","surface":"steht","translation":"قرار داشتن / ایستادن"},{"lemma":"dass","partOfSpeech":"conjunction","surface":"dass","translation":"که"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"zehn","partOfSpeech":"number","surface":"zehn","translation":"ده"},{"lemma":"Minute","partOfSpeech":"noun","surface":"Minuten","translation":"دقیقه"},{"lemma":"Verspätung","partOfSpeech":"noun","surface":"Verspätung","translation":"تاخیر"},{"lemma":"haben","partOfSpeech":"verb","suffix":".","surface":"haben","translation":"داشتن"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
  SET v_t_9=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_lena,4,'learner','Das ist weniger, als ich erwartet habe.','این کمتر از چیزی است که انتظار داشتم.',51,NULL,NULL,'das ist weniger als ich erwartet habe',NULL,'[{"lemma":"das","partOfSpeech":"pronoun","surface":"Das","translation":"این / آن"},{"lemma":"sein","partOfSpeech":"verb","surface":"ist","translation":"بودن"},{"lemma":"weniger","partOfSpeech":"adverb","suffix":",","surface":"weniger","translation":"کمتر"},{"lemma":"als","partOfSpeech":"conjunction","surface":"als","translation":"از / نسبت به"},{"lemma":"ich","partOfSpeech":"pronoun","surface":"ich","translation":"من"},{"lemma":"erwarten","partOfSpeech":"verb","surface":"erwartet","translation":"انتظار داشتن"},{"lemma":"haben","partOfSpeech":"verb","suffix":".","surface":"habe","translation":"داشتن"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
