  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_ben,5,'character','Vielleicht erreichen wir den Nachtbus doch.','شاید بالاخره به اتوبوس شبانه برسیم.',51,NULL,NULL,NULL,NULL,'[{"lemma":"vielleicht","partOfSpeech":"adverb","surface":"Vielleicht","translation":"شاید"},{"lemma":"erreichen","partOfSpeech":"verb","surface":"erreichen","translation":"رسیدن به"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"der","partOfSpeech":"article","surface":"den","translation":"حرف تعریف"},{"lemma":"Nachtbus","partOfSpeech":"noun","surface":"Nachtbus","translation":"اتوبوس شبانه"},{"lemma":"doch","partOfSpeech":"particle","suffix":".","surface":"doch","translation":"بالاخره / با این حال"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
