  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_lena,6,'learner','Ich prüfe die Ankunftszeit noch einmal.','زمان رسیدن را یک بار دیگر بررسی می‌کنم.',51,NULL,NULL,'ich prüfe die ankunftszeit noch einmal',NULL,'[{"lemma":"ich","partOfSpeech":"pronoun","surface":"Ich","translation":"من"},{"lemma":"prüfen","partOfSpeech":"verb","surface":"prüfe","translation":"بررسی کردن"},{"lemma":"der","partOfSpeech":"article","surface":"die","translation":"حرف تعریف"},{"lemma":"Ankunftszeit","partOfSpeech":"noun","surface":"Ankunftszeit","translation":"زمان رسیدن"},{"lemma":"noch","partOfSpeech":"adverb","surface":"noch","translation":"هنوز"},{"lemma":"einmal","partOfSpeech":"adverb","suffix":".","surface":"einmal","translation":"یک بار"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
