  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_lena,6,'learner','Danke, so sind wir schneller.','ممنون، این‌طوری سریع‌تر می‌رسیم.',51,NULL,NULL,'danke so sind wir schneller',NULL,'[{"lemma":"danke","partOfSpeech":"interjection","suffix":",","surface":"Danke","translation":"ممنون"},{"lemma":"so","partOfSpeech":"adverb","surface":"so","translation":"این طور / آن طور"},{"lemma":"sein","partOfSpeech":"verb","surface":"sind","translation":"بودن"},{"lemma":"wir","partOfSpeech":"pronoun","surface":"wir","translation":"ما"},{"lemma":"schnell","partOfSpeech":"adjective","suffix":".","surface":"schneller","translation":"سریع"}]','Gegensatz mit obwohl','با obwohl یک مانع بیان می‌شود و جملهٔ اصلی نشان می‌دهد که عمل با وجود آن ادامه دارد.','{"focus":"obwohl_contrast","structures":["obwohl clause","travel narration","modal verbs"]}','{"cefr":"B1","course":"de-fa","series":98}');
