  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_ben,v_c_lena,'Zwei Möglichkeiten vergleichen','مقایسهٔ دو گزینه','Die Freunde vergleichen Preis, Umstieg und Komfort der beiden Verbindungen.','دو دوست قیمت، تعویض قطار و راحتی دو مسیر را مقایسه می‌کنند.','story','lena-ben-b1-travel-problems',14,52,180,2,'validated','{"relationship":"friends","context":"travel-connection","cefr":"B1","storyArc":"choose-direct-connection"}');
