  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_ben,1,'character','Die direkte Verbindung kostet zwölf Euro mehr.','مسیر مستقیم دوازده یورو گران‌تر است.',52,NULL,NULL,NULL,NULL,'[{"surface":"Die","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"direkte","lemma":"direkt","translation":"مستقیم","partOfSpeech":"adjective"},{"surface":"Verbindung","lemma":"Verbindung","translation":"مسیر / ارتباط","partOfSpeech":"noun"},{"surface":"kostet","lemma":"kosten","translation":"قیمت داشتن","partOfSpeech":"verb"},{"surface":"zwölf","lemma":"zwölf","translation":"دوازده","partOfSpeech":"number"},{"surface":"Euro","lemma":"Euro","translation":"یورو","partOfSpeech":"noun"},{"surface":"mehr","lemma":"mehr","translation":"دیگه / بیشتر","partOfSpeech":"adverb","suffix":"."}]','Vorlieben mit hätte lieber','با hätte lieber ترجیح مؤدبانه بیان می‌شود؛ مصدر یا متمم جمله انتخاب موردنظر را روشن می‌کند.','{"focus":"preference_konjunktiv_ii","structures":["hätte lieber","würde lieber","travel comparison"]}','{"cefr":"B1","course":"de-fa","series":99}');
  SET v_t_7=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_lena,2,'learner','Dafür müssen wir nicht noch einmal umsteigen.','در عوض لازم نیست دوباره قطار عوض کنیم.',52,NULL,NULL,'dafür müssen wir nicht noch einmal umsteigen',NULL,'[{"surface":"Dafür","lemma":"dafür","translation":"برای آن / برای این کار","partOfSpeech":"adverb"},{"surface":"müssen","lemma":"müssen","translation":"مجبور بودن / باید","partOfSpeech":"verb"},{"surface":"wir","lemma":"wir","translation":"ما","partOfSpeech":"pronoun"},{"surface":"nicht","lemma":"nicht","translation":"نه / نیست","partOfSpeech":"particle"},{"surface":"noch","lemma":"noch","translation":"هنوز","partOfSpeech":"adverb"},{"surface":"einmal","lemma":"einmal","translation":"یک بار","partOfSpeech":"adverb"},{"surface":"umsteigen","lemma":"umsteigen","translation":"قطار عوض کردن / خط عوض کردن","partOfSpeech":"verb","suffix":"."}]','Vorlieben mit hätte lieber','با hätte lieber ترجیح مؤدبانه بیان می‌شود؛ مصدر یا متمم جمله انتخاب موردنظر را روشن می‌کند.','{"focus":"preference_konjunktiv_ii","structures":["hätte lieber","würde lieber","travel comparison"]}','{"cefr":"B1","course":"de-fa","series":99}');
