  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_ben,v_c_lena,'Ruhig unterwegs','آرام در مسیر','Während der ruhigen Fahrt prüfen die Freunde die Ankunft und informieren das Hotel.','در طول مسیر آرام، دو دوست زمان رسیدن را بررسی می‌کنند و به هتل خبر می‌دهند.','story','lena-ben-b1-travel-problems',18,52,180,2,'validated','{"relationship":"friends","context":"arrival","cefr":"B1","storyArc":"arrive-after-problems"}');
