  INSERT INTO activities(lesson_id,activity_type,sort_order,turn_id,word_id,prompt,instruction,difficulty,config,metadata) VALUES(v_l_2,'reading_comprehension',8,NULL,NULL,'مکالمه را بخوان و پاسخ بده',NULL,52,'{"source":"lesson_story","question":"چه چیزی را به هتل اطلاع می‌دهند؟","choices":["اینکه در راه‌اند","اینکه سفر را لغو کرده‌اند","اینکه فردا می‌رسند"],"correctIndex":0}','{"cefr":"B1","series":100}');
  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_ben,v_c_lena,'Ankunft in Berlin','رسیدن به برلین','Der Zug erreicht Berlin, und die Freunde bereiten sich auf das Aussteigen vor.','قطار به برلین می‌رسد و دو دوست برای پیاده شدن آماده می‌شوند.','story','lena-ben-b1-travel-problems',19,52,180,3,'validated','{"relationship":"friends","context":"arrival","cefr":"B1","storyArc":"arrive-after-problems"}');
  SET v_l_3=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_ben,1,'character','Wir erreichen gleich den Berliner Hauptbahnhof.','همین حالا به ایستگاه مرکزی برلین می‌رسیم.',52,NULL,NULL,NULL,NULL,'[{"surface":"Wir","lemma":"wir","translation":"ما","partOfSpeech":"pronoun"},{"surface":"erreichen","lemma":"erreichen","translation":"رسیدن به","partOfSpeech":"verb"},{"surface":"gleich","lemma":"gleich","translation":"همین الان","partOfSpeech":"adverb"},{"surface":"den","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Berliner","lemma":"Berliner","translation":"برلینی","partOfSpeech":"adjective"},{"surface":"Hauptbahnhof","lemma":"Hauptbahnhof","translation":"ایستگاه مرکزی","partOfSpeech":"noun","suffix":"."}]','Eine Reise abschließen','برای روایت پایان سفر از Perfekt، Präteritum و واژه‌هایی مانند endlich، doch و am Ende استفاده می‌شود.','{"focus":"travel_arrival_narration","structures":["Perfekt arrival","am Ende","separable arrival verbs"]}','{"cefr":"B1","course":"de-fa","series":100}');
  SET v_t_13=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_lena,2,'learner','Am Ende sind wir doch angekommen.','آخرش بالاخره رسیدیم.',52,NULL,NULL,'am ende sind wir doch angekommen',NULL,'[{"surface":"Am","lemma":"an","translation":"در / در روز","partOfSpeech":"preposition"},{"surface":"Ende","lemma":"Ende","translation":"پایان","partOfSpeech":"noun"},{"surface":"sind","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"wir","lemma":"wir","translation":"ما","partOfSpeech":"pronoun"},{"surface":"doch","lemma":"doch","translation":"بالاخره / با این حال","partOfSpeech":"particle"},{"surface":"angekommen","lemma":"ankommen","translation":"رسیدن","partOfSpeech":"verb","suffix":"."}]','Eine Reise abschließen','برای روایت پایان سفر از Perfekt، Präteritum و واژه‌هایی مانند endlich، doch و am Ende استفاده می‌شود.','{"focus":"travel_arrival_narration","structures":["Perfekt arrival","am Ende","separable arrival verbs"]}','{"cefr":"B1","course":"de-fa","series":100}');
  SET v_t_14=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_ben,3,'character','Der Zug fährt jetzt auf Gleis acht ein.','قطار حالا وارد خط هشت می‌شود.',52,NULL,NULL,NULL,NULL,'[{"surface":"Der","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Zug","lemma":"Zug","translation":"قطار","partOfSpeech":"noun"},{"surface":"fährt","lemma":"einfahren","translation":"وارد شدن","partOfSpeech":"verb"},{"surface":"jetzt","lemma":"jetzt","translation":"حالا / اکنون","partOfSpeech":"adverb"},{"surface":"auf","lemma":"auf","translation":"روی / برای","partOfSpeech":"preposition"},{"surface":"Gleis","lemma":"Gleis","translation":"سکوی قطار / خط","partOfSpeech":"noun"},{"surface":"acht","lemma":"acht","translation":"هشت","partOfSpeech":"number"},{"surface":"ein","lemma":"einfahren","translation":"وارد شدن","partOfSpeech":"verb","suffix":"."}]','Eine Reise abschließen','برای روایت پایان سفر از Perfekt، Präteritum و واژه‌هایی مانند endlich، doch و am Ende استفاده می‌شود.','{"focus":"travel_arrival_narration","structures":["Perfekt arrival","am Ende","separable arrival verbs"]}','{"cefr":"B1","course":"de-fa","series":100}');
  SET v_t_15=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_lena,4,'learner','Ich sammle schnell unser Gepäck.','سریع وسایلمان را جمع می‌کنم.',52,NULL,NULL,'ich sammle schnell unser gepäck',NULL,'[{"surface":"Ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"sammle","lemma":"sammeln","translation":"جمع کردن","partOfSpeech":"verb"},{"surface":"schnell","lemma":"schnell","translation":"سریع","partOfSpeech":"adjective"},{"surface":"unser","lemma":"unser","translation":"مال ما / ما","partOfSpeech":"determiner"},{"surface":"Gepäck","lemma":"Gepäck","translation":"بار / چمدان","partOfSpeech":"noun","suffix":"."}]','Eine Reise abschließen','برای روایت پایان سفر از Perfekt، Präteritum و واژه‌هایی مانند endlich، doch و am Ende استفاده می‌شود.','{"focus":"travel_arrival_narration","structures":["Perfekt arrival","am Ende","separable arrival verbs"]}','{"cefr":"B1","course":"de-fa","series":100}');
