  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_ben,1,'character','Endlich stehen wir vor dem Bahnhof.','بالاخره جلوی ایستگاه ایستاده‌ایم.',52,NULL,NULL,NULL,NULL,'[{"surface":"Endlich","lemma":"endlich","translation":"بالاخره","partOfSpeech":"adverb"},{"surface":"stehen","lemma":"stehen","translation":"قرار داشتن / ایستادن","partOfSpeech":"verb"},{"surface":"wir","lemma":"wir","translation":"ما","partOfSpeech":"pronoun"},{"surface":"vor","lemma":"vor","translation":"از / جلوی","partOfSpeech":"preposition"},{"surface":"dem","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Bahnhof","lemma":"Bahnhof","translation":"ایستگاه قطار","partOfSpeech":"noun","suffix":"."}]','Eine Reise abschließen','برای روایت پایان سفر از Perfekt، Präteritum و واژه‌هایی مانند endlich، doch و am Ende استفاده می‌شود.','{"focus":"travel_arrival_narration","structures":["Perfekt arrival","am Ende","separable arrival verbs"]}','{"cefr":"B1","course":"de-fa","series":100}');
  SET v_t_19=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_lena,2,'learner','Die Reise war länger als geplant.','سفر طولانی‌تر از چیزی بود که برنامه‌ریزی کرده بودیم.',52,NULL,NULL,'die reise war länger als geplant',NULL,'[{"surface":"Die","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Reise","lemma":"Reise","translation":"سفر","partOfSpeech":"noun"},{"surface":"war","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"länger","lemma":"lang","translation":"طولانی / بلند","partOfSpeech":"adjective"},{"surface":"als","lemma":"als","translation":"از / نسبت به","partOfSpeech":"conjunction"},{"surface":"geplant","lemma":"planen","translation":"برنامه‌ریزی کردن","partOfSpeech":"verb","suffix":"."}]','Eine Reise abschließen','برای روایت پایان سفر از Perfekt، Präteritum و واژه‌هایی مانند endlich، doch و am Ende استفاده می‌شود.','{"focus":"travel_arrival_narration","structures":["Perfekt arrival","am Ende","separable arrival verbs"]}','{"cefr":"B1","course":"de-fa","series":100}');
