  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Schlaf und Beschwerden','خواب و ناراحتی‌ها','Mia beschreibt genauer, wie lange die Müdigkeit dauert und welche Beschwerden sie hat.','میا دقیق‌تر توضیح می‌دهد خستگی‌اش از چه زمانی شروع شده و چه ناراحتی‌هایی دارد.','story','mia-sara-b1-health-routine',2,53,180,2,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"notice-tiredness"}'); SET v_l_2=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,1,'character','Wie lange fühlst du dich schon so?','چند وقت است که این‌طور احساس می‌کنی؟',53,NULL,NULL,NULL,NULL,'[{"surface":"Wie","lemma":"wie","translation":"چطور / چگونه","partOfSpeech":"adverb"},{"surface":"lange","lemma":"lang","translation":"طولانی / بلند","partOfSpeech":"adjective"},{"surface":"fühlst","lemma":"sich fühlen","translation":"احساس کردن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"dich","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"schon","lemma":"schon","translation":"قبلا / تا حالا","partOfSpeech":"adverb"},{"surface":"so","lemma":"so","translation":"این طور / آن طور","partOfSpeech":"adverb","suffix":"?"}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_7=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_mia,2,'learner','Seit drei Tagen bin ich ständig erschöpft.','سه روز است که مدام بی‌حال و خسته‌ام.',53,NULL,NULL,'seit drei tagen bin ich ständig erschöpft',NULL,'[{"surface":"Seit","lemma":"seit","translation":"از / از زمان","partOfSpeech":"preposition"},{"surface":"drei","lemma":"drei","translation":"سه","partOfSpeech":"number"},{"surface":"Tagen","lemma":"Tag","translation":"روز","partOfSpeech":"noun"},{"surface":"bin","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"ständig","lemma":"ständig","translation":"مدام","partOfSpeech":"adverb"},{"surface":"erschöpft","lemma":"erschöpft","translation":"از پا افتاده / خسته","partOfSpeech":"adjective","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_8=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,3,'character','Hast du auch Kopfschmerzen oder Fieber?','سردرد یا تب هم داری؟',53,NULL,NULL,NULL,NULL,'[{"surface":"Hast","lemma":"haben","translation":"داشتن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"auch","lemma":"auch","translation":"هم / همچنین","partOfSpeech":"adverb"},{"surface":"Kopfschmerzen","lemma":"Kopfschmerz","translation":"سردرد","partOfSpeech":"noun"},{"surface":"oder","lemma":"oder","translation":"یا","partOfSpeech":"conjunction"},{"surface":"Fieber","lemma":"Fieber","translation":"تب","partOfSpeech":"noun","suffix":"?"}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_9=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_mia,4,'learner','Nein, aber ich kann mich schlecht konzentrieren.','نه، اما نمی‌توانم خوب تمرکز کنم.',53,NULL,NULL,'nein aber ich kann mich schlecht konzentrieren',NULL,'[{"surface":"Nein","lemma":"nein","translation":"نه","partOfSpeech":"interjection","suffix":","},{"surface":"aber","lemma":"aber","translation":"اما","partOfSpeech":"conjunction"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"kann","lemma":"können","translation":"توانستن / بتوان","partOfSpeech":"verb"},{"surface":"mich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"schlecht","lemma":"schlecht","translation":"بد","partOfSpeech":"adjective"},{"surface":"konzentrieren","lemma":"sich konzentrieren","translation":"تمرکز کردن","partOfSpeech":"verb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_10=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,5,'character','Trinkst du tagsüber genug Wasser?','در طول روز آب کافی می‌نوشی؟',53,NULL,NULL,NULL,NULL,'[{"surface":"Trinkst","lemma":"trinken","translation":"نوشیدن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"tagsüber","lemma":"tagsüber","translation":"در طول روز","partOfSpeech":"adverb"},{"surface":"genug","lemma":"genug","translation":"کافی","partOfSpeech":"adverb"},{"surface":"Wasser","lemma":"Wasser","translation":"آب","partOfSpeech":"noun","suffix":"?"}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_11=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_mia,6,'learner','Wahrscheinlich viel zu wenig.','احتمالاً خیلی کم.',53,NULL,NULL,'wahrscheinlich viel zu wenig',NULL,'[{"surface":"Wahrscheinlich","lemma":"wahrscheinlich","translation":"احتمالا","partOfSpeech":"adverb"},{"surface":"viel","lemma":"viel","translation":"زیاد / مقدار زیاد","partOfSpeech":"determiner"},{"surface":"zu","lemma":"zu","translation":"بیش از حد","partOfSpeech":"adverb"},{"surface":"wenig","lemma":"wenig","translation":"کم","partOfSpeech":"adverb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_12=LAST_INSERT_ID();
