  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Zu wenig Erholung','استراحت ناکافی','Sara hilft Mia, den Zusammenhang zwischen Arbeit, Pausen und Erholung zu erkennen.','سارا به میا کمک می‌کند ارتباط میان کار، وقفه و استراحت را بفهمد.','story','mia-sara-b1-health-routine',3,53,180,3,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"notice-tiredness"}'); SET v_l_3=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_sara,1,'character','Du hast diese Woche sehr viel gearbeitet.','این هفته خیلی زیاد کار کرده‌ای.',53,NULL,NULL,NULL,NULL,'[{"surface":"Du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"hast","lemma":"haben","translation":"داشتن","partOfSpeech":"verb"},{"surface":"diese","lemma":"dieser","translation":"این","partOfSpeech":"determiner"},{"surface":"Woche","lemma":"Woche","translation":"هفته","partOfSpeech":"noun"},{"surface":"sehr","lemma":"sehr","translation":"خیلی / بسیار","partOfSpeech":"adverb"},{"surface":"viel","lemma":"viel","translation":"زیاد / مقدار زیاد","partOfSpeech":"determiner"},{"surface":"gearbeitet","lemma":"arbeiten","translation":"کار کردن","partOfSpeech":"verb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_13=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_mia,2,'learner','Ja, ich musste zwei Aufgaben gleichzeitig erledigen.','بله، مجبور بودم دو کار را هم‌زمان انجام بدهم.',53,NULL,NULL,'ja ich musste zwei aufgaben gleichzeitig erledigen',NULL,'[{"surface":"Ja","lemma":"ja","translation":"بله / آره","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"musste","lemma":"müssen","translation":"مجبور بودن / باید","partOfSpeech":"verb"},{"surface":"zwei","lemma":"zwei","translation":"دو","partOfSpeech":"number"},{"surface":"Aufgaben","lemma":"Aufgabe","translation":"وظیفه / تکلیف","partOfSpeech":"noun"},{"surface":"gleichzeitig","lemma":"gleichzeitig","translation":"هم‌زمان","partOfSpeech":"adverb"},{"surface":"erledigen","lemma":"erledigen","translation":"انجام دادن / تمام کردن","partOfSpeech":"verb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_14=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_sara,3,'character','Pausen sind genauso wichtig wie die Arbeit.','استراحت‌ها درست به اندازهٔ کار مهم‌اند.',53,NULL,NULL,NULL,NULL,'[{"surface":"Pausen","lemma":"Pause","translation":"استراحت","partOfSpeech":"noun"},{"surface":"sind","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"genauso","lemma":"genauso","translation":"دقیقاً همان‌قدر","partOfSpeech":"adverb"},{"surface":"wichtig","lemma":"wichtig","translation":"مهم","partOfSpeech":"adjective"},{"surface":"wie","lemma":"wie","translation":"مانند / همان‌طور که","partOfSpeech":"conjunction"},{"surface":"die","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Arbeit","lemma":"Arbeit","translation":"کار","partOfSpeech":"noun","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_15=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_mia,4,'learner','Ich vergesse oft, rechtzeitig eine Pause zu machen.','اغلب فراموش می‌کنم به‌موقع استراحت کنم.',53,NULL,NULL,'ich vergesse oft rechtzeitig eine pause zu machen',NULL,'[{"surface":"Ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"vergesse","lemma":"vergessen","translation":"فراموش کردن","partOfSpeech":"verb"},{"surface":"oft","lemma":"oft","translation":"اغلب","partOfSpeech":"adverb","suffix":","},{"surface":"rechtzeitig","lemma":"rechtzeitig","translation":"به موقع","partOfSpeech":"adverb"},{"surface":"eine","lemma":"ein","translation":"یک / حرف تعریف نامعین","partOfSpeech":"article"},{"surface":"Pause","lemma":"Pause","translation":"استراحت","partOfSpeech":"noun"},{"surface":"zu","lemma":"zu","translation":"بیش از حد / خیلی","partOfSpeech":"particle"},{"surface":"machen","lemma":"machen","translation":"انجام دادن","partOfSpeech":"verb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_16=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_sara,5,'character','Dein Körper braucht Zeit zur Erholung.','بدنت برای بازیابی به زمان نیاز دارد.',53,NULL,NULL,NULL,NULL,'[{"surface":"Dein","lemma":"dein","translation":"مال تو / تو","partOfSpeech":"determiner"},{"surface":"Körper","lemma":"Körper","translation":"بدن","partOfSpeech":"noun"},{"surface":"braucht","lemma":"brauchen","translation":"نیاز داشتن / لازم داشتن","partOfSpeech":"verb"},{"surface":"Zeit","lemma":"Zeit","translation":"وقت / زمان","partOfSpeech":"noun"},{"surface":"zur","lemma":"zu","translation":"به / به سمت","partOfSpeech":"preposition"},{"surface":"Erholung","lemma":"Erholung","translation":"استراحت / بازیابی","partOfSpeech":"noun","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_17=LAST_INSERT_ID();
