  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Heute früher zur Ruhe kommen','امشب زودتر استراحت کردن','Mia nimmt die Müdigkeit ernst und entscheidet sich für einen ruhigeren Abend.','میا خستگی را جدی می‌گیرد و تصمیم می‌گیرد عصر آرام‌تری داشته باشد.','story','mia-sara-b1-health-routine',4,53,180,4,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"notice-tiredness"}'); SET v_l_4=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,1,'character','Wenn es morgen nicht besser ist, geh zum Arzt.','اگر فردا بهتر نشدی، پیش پزشک برو.',53,NULL,NULL,NULL,NULL,'[{"surface":"Wenn","lemma":"wenn","translation":"اگر / وقتی","partOfSpeech":"conjunction"},{"surface":"es","lemma":"es","translation":"آن / این / ضمیر خنثی","partOfSpeech":"pronoun"},{"surface":"morgen","lemma":"morgen","translation":"فردا","partOfSpeech":"adverb"},{"surface":"nicht","lemma":"nicht","translation":"نه / نیست","partOfSpeech":"particle"},{"surface":"besser","lemma":"gut","translation":"خوب","partOfSpeech":"adjective"},{"surface":"ist","lemma":"sein","translation":"بودن","partOfSpeech":"verb","suffix":","},{"surface":"geh","lemma":"gehen","translation":"رفتن","partOfSpeech":"verb"},{"surface":"zum","lemma":"zu","translation":"به / به سمت","partOfSpeech":"preposition"},{"surface":"Arzt","lemma":"Arzt","translation":"دکتر","partOfSpeech":"noun","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_19=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,2,'learner','Ich möchte zuerst eine ruhige Nacht abwarten.','می‌خواهم اول یک شب آرام را صبر کنم.',53,NULL,NULL,'ich möchte zuerst eine ruhige nacht abwarten',NULL,'[{"surface":"Ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"möchte","lemma":"mögen","translation":"خواستن / دوست داشتن","partOfSpeech":"verb"},{"surface":"zuerst","lemma":"zuerst","translation":"اول / ابتدا","partOfSpeech":"adverb"},{"surface":"eine","lemma":"ein","translation":"یک / حرف تعریف نامعین","partOfSpeech":"article"},{"surface":"ruhige","lemma":"ruhig","translation":"آرام","partOfSpeech":"adjective"},{"surface":"Nacht","lemma":"Nacht","translation":"شب","partOfSpeech":"noun"},{"surface":"abwarten","lemma":"abwarten","translation":"صبر کردن","partOfSpeech":"verb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_20=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,3,'character','Das ist vernünftig, aber nimm die Müdigkeit ernst.','این منطقی است، اما خستگی را جدی بگیر.',53,NULL,NULL,NULL,NULL,'[{"surface":"Das","lemma":"das","translation":"این / آن","partOfSpeech":"pronoun"},{"surface":"ist","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"vernünftig","lemma":"vernünftig","translation":"منطقی","partOfSpeech":"adjective","suffix":","},{"surface":"aber","lemma":"aber","translation":"اما","partOfSpeech":"conjunction"},{"surface":"nimm","lemma":"nehmen","translation":"گرفتن / مصرف کردن","partOfSpeech":"verb"},{"surface":"die","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Müdigkeit","lemma":"Müdigkeit","translation":"خستگی","partOfSpeech":"noun"},{"surface":"ernst","lemma":"ernst","translation":"جدی","partOfSpeech":"adjective","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_21=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,4,'learner','Heute sage ich alle späten Termine ab.','امروز همهٔ قرارهای دیرهنگام را لغو می‌کنم.',53,NULL,NULL,'heute sage ich alle späten termine ab',NULL,'[{"surface":"Heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"sage","lemma":"absagen","translation":"لغو کردن","partOfSpeech":"verb"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"alle","lemma":"alle","translation":"همه","partOfSpeech":"determiner"},{"surface":"späten","lemma":"spät","translation":"دیر","partOfSpeech":"adjective"},{"surface":"Termine","lemma":"Termin","translation":"قرار / وقت","partOfSpeech":"noun"},{"surface":"ab","lemma":"absagen","translation":"لغو کردن","partOfSpeech":"verb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_22=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,5,'character','Dann kannst du dich am Abend ausruhen.','آن وقت می‌توانی عصر استراحت کنی.',53,NULL,NULL,NULL,NULL,'[{"surface":"Dann","lemma":"dann","translation":"بعد / سپس","partOfSpeech":"adverb"},{"surface":"kannst","lemma":"können","translation":"توانستن / بتوان","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"dich","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"am","lemma":"an","translation":"در / در روز","partOfSpeech":"preposition"},{"surface":"Abend","lemma":"Abend","translation":"عصر / شب","partOfSpeech":"noun"},{"surface":"ausruhen","lemma":"sich ausruhen","translation":"استراحت کردن","partOfSpeech":"verb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_23=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,6,'learner','Danke, ich ruhe mich heute richtig aus.','ممنون، امروز درست استراحت می‌کنم.',53,NULL,NULL,'danke ich ruhe mich heute richtig aus',NULL,'[{"surface":"Danke","lemma":"danke","translation":"ممنون","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"ruhe","lemma":"sich ausruhen","translation":"استراحت کردن","partOfSpeech":"verb"},{"surface":"mich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"richtig","lemma":"richtig","translation":"درست","partOfSpeech":"adjective"},{"surface":"aus","lemma":"sich ausruhen","translation":"استراحت کردن","partOfSpeech":"verb","suffix":"."}]','Beschwerden mit seit beschreiben','با seit می‌توان شروع یک وضعیت ادامه‌دار را بیان کرد؛ فعل در زمان حال می‌ماند.','{"focus":"seit_duration_health","structures":["seit + Dativ","reflexive sich fühlen","health advice"]}','{"cefr":"B1","course":"de-fa","series":101}'); SET v_t_24=LAST_INSERT_ID();
