  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Beim Arzt','پیش دکتر','Mia erzählt Sara von der Untersuchung und gibt die ärztliche Empfehlung als berichtete Rede wieder.','میا دربارهٔ معاینه به سارا می‌گوید و توصیهٔ دکتر را به‌صورت نقل‌قول غیرمستقیم بازگو می‌کند.','story','mia-sara-b1-health-routine',5,54,180,1,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"report-doctor-advice"}'); SET v_l_1=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_sara,1,'character','Warst du heute beim Arzt?','امروز پیش دکتر بودی؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Warst","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"beim","lemma":"bei","translation":"هنگام / موقع","partOfSpeech":"preposition"},{"surface":"Arzt","lemma":"Arzt","translation":"دکتر","partOfSpeech":"noun","suffix":"?"}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_1=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_mia,2,'learner','Ja, der Arzt hat mich gründlich untersucht.','بله، دکتر من را کامل معاینه کرد.',54,NULL,NULL,'ja der arzt hat mich gründlich untersucht',NULL,'[{"surface":"Ja","lemma":"ja","translation":"بله / آره","partOfSpeech":"interjection","suffix":","},{"surface":"der","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Arzt","lemma":"Arzt","translation":"دکتر","partOfSpeech":"noun"},{"surface":"hat","lemma":"haben","translation":"داشتن","partOfSpeech":"verb"},{"surface":"mich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"gründlich","lemma":"gründlich","translation":"کامل / دقیق","partOfSpeech":"adjective"},{"surface":"untersucht","lemma":"untersuchen","translation":"معاینه کردن","partOfSpeech":"verb","suffix":"."}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_2=LAST_INSERT_ID();
