  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Ruhe statt Arbeit','استراحت به‌جای کار','Mia plant eine kurze Krankmeldung und erklärt die Hinweise zu Wasser und Schlaf.','میا برای مرخصی بیماری کوتاه برنامه می‌ریزد و توصیه‌های مربوط به آب و خواب را توضیح می‌دهد.','story','mia-sara-b1-health-routine',6,54,180,2,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"plan-recovery"}'); SET v_l_2=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,1,'character','Musst du morgen zur Arbeit gehen?','باید فردا سر کار بروی؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Musst","lemma":"müssen","translation":"مجبور بودن / باید","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"morgen","lemma":"morgen","translation":"فردا","partOfSpeech":"adverb"},{"surface":"zur","lemma":"zu","translation":"به / به سمت","partOfSpeech":"preposition"},{"surface":"Arbeit","lemma":"Arbeit","translation":"کار","partOfSpeech":"noun"},{"surface":"gehen","lemma":"gehen","translation":"رفتن","partOfSpeech":"verb","suffix":"?"}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_7=LAST_INSERT_ID();
