  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Ein ruhiger Abend','یک شب آرام','Sara hilft Mia, den Abend ruhig zu organisieren und belastende Aufgaben zu vermeiden.','سارا به میا کمک می‌کند شب آرامی برنامه‌ریزی کند و از کارهای خسته‌کننده دور بماند.','story','mia-sara-b1-health-routine',7,54,180,3,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"support-evening-rest"}'); SET v_l_3=LAST_INSERT_ID();
