  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_mia,2,'learner','Ja, ich will heute Abend wirklich früh schlafen.','بله، می‌خواهم امشب واقعاً زود بخوابم.',54,NULL,NULL,'ja ich will heute abend wirklich früh schlafen',NULL,'[{"surface":"Ja","lemma":"ja","translation":"بله / آره","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"will","lemma":"wollen","translation":"خواستن","partOfSpeech":"verb"},{"surface":"heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"Abend","lemma":"Abend","translation":"عصر / شب","partOfSpeech":"noun"},{"surface":"wirklich","lemma":"wirklich","translation":"واقعا","partOfSpeech":"adverb"},{"surface":"früh","lemma":"früh","translation":"زودتر","partOfSpeech":"adverb"},{"surface":"schlafen","lemma":"schlafen","translation":"خوابیدن","partOfSpeech":"verb","suffix":"."}]','Indirekte Rede mit dass und sollen','با dass گفتهٔ دکتر به‌صورت غیرمستقیم نقل می‌شود؛ فعل صرف‌شده در پایان جملهٔ وابسته قرار می‌گیرد و sollen توصیه را بیان می‌کند.','{"focus":"reported_medical_advice","structures":["dass clause","sollen for advice","reported speech","wenn clause"]}','{"cefr":"B1","course":"de-fa","series":102}'); SET v_t_14=LAST_INSERT_ID();
