  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Am nächsten Morgen','صبح روز بعد','Sara fragt nach Mias Zustand; Mia vergleicht ihre Beschwerden mit dem Vortag und nennt den Plan des Arztes.','سارا دربارهٔ حال میا می‌پرسد؛ میا نشانه‌هایش را با روز قبل مقایسه می‌کند و برنامهٔ دکتر را می‌گوید.','story','mia-sara-b1-health-routine',9,54,180,1,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"check-recovery"}'); SET v_l_1=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_sara,1,'character','Wie geht es dir heute Morgen?','امروز صبح حالت چطور است؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Wie","lemma":"wie","translation":"چطور / چگونه","partOfSpeech":"adverb"},{"surface":"geht","lemma":"gehen","translation":"رفتن","partOfSpeech":"verb"},{"surface":"es","lemma":"es","translation":"آن / این / ضمیر خنثی","partOfSpeech":"pronoun"},{"surface":"dir","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"heute","lemma":"heute","translation":"امروز","partOfSpeech":"adverb"},{"surface":"Morgen","lemma":"Morgen","translation":"صبح","partOfSpeech":"noun","suffix":"?"}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_1=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_mia,2,'learner','Etwas besser, aber ich bin noch müde.','کمی بهترم، اما هنوز خسته‌ام.',54,NULL,NULL,'etwas besser aber ich bin noch müde',NULL,'[{"surface":"Etwas","lemma":"etwas","translation":"چیزی / یک چیزی","partOfSpeech":"pronoun"},{"surface":"besser","lemma":"gut","translation":"خوب","partOfSpeech":"adjective","suffix":","},{"surface":"aber","lemma":"aber","translation":"اما","partOfSpeech":"conjunction"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"bin","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"noch","lemma":"noch","translation":"هنوز","partOfSpeech":"adverb"},{"surface":"müde","lemma":"müde","translation":"خسته","partOfSpeech":"adjective","suffix":"."}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_2=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_1,v_c_sara,3,'character','Hast du den Rat des Arztes befolgt?','توصیهٔ دکتر را انجام دادی؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Hast","lemma":"haben","translation":"داشتن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"den","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Rat","lemma":"Rat","translation":"توصیه / راهنمایی","partOfSpeech":"noun"},{"surface":"des","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Arztes","lemma":"Arzt","translation":"دکتر","partOfSpeech":"noun"},{"surface":"befolgt","lemma":"befolgen","translation":"پیروی کردن / انجام دادن","partOfSpeech":"verb","suffix":"?"}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_3=LAST_INSERT_ID();
