  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Beschwerden beobachten','بررسی نشانه‌ها','Mia beobachtet Kopfschmerzen und Temperatur und bereitet einen möglichen Praxisbesuch vor.','میا سردرد و دمای بدنش را بررسی می‌کند و برای مراجعهٔ احتمالی به مطب آماده می‌شود.','story','mia-sara-b1-health-routine',10,54,180,2,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"monitor-symptoms"}'); SET v_l_2=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,1,'character','Hast du noch Kopfschmerzen?','هنوز سردرد داری؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Hast","lemma":"haben","translation":"داشتن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"noch","lemma":"noch","translation":"هنوز","partOfSpeech":"adverb"},{"surface":"Kopfschmerzen","lemma":"Kopfschmerz","translation":"سردرد","partOfSpeech":"noun","suffix":"?"}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_7=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_mia,2,'learner','Ein bisschen, besonders am Nachmittag.','کمی، به‌خصوص بعدازظهر.',54,NULL,NULL,'ein bisschen besonders am nachmittag',NULL,'[{"surface":"Ein","lemma":"ein","translation":"یک / حرف تعریف نامعین","partOfSpeech":"article"},{"surface":"bisschen","lemma":"bisschen","translation":"کمی","partOfSpeech":"noun","suffix":","},{"surface":"besonders","lemma":"besonders","translation":"مخصوصا","partOfSpeech":"adverb"},{"surface":"am","lemma":"an","translation":"در / در روز","partOfSpeech":"preposition"},{"surface":"Nachmittag","lemma":"Nachmittag","translation":"بعدازظهر","partOfSpeech":"noun","suffix":"."}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_8=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,3,'character','Dann solltest du deine Temperatur messen.','پس بهتر است دمای بدنت را اندازه بگیری.',54,NULL,NULL,NULL,NULL,'[{"surface":"Dann","lemma":"dann","translation":"بعد / سپس","partOfSpeech":"adverb"},{"surface":"solltest","lemma":"sollen","translation":"باید / قرار است","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"deine","lemma":"dein","translation":"مال تو / تو","partOfSpeech":"determiner"},{"surface":"Temperatur","lemma":"Temperatur","translation":"دما / درجه حرارت","partOfSpeech":"noun"},{"surface":"messen","lemma":"messen","translation":"اندازه گرفتن","partOfSpeech":"verb","suffix":"."}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_9=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_mia,4,'learner','Ja, ich messe sie gleich.','بله، همین حالا آن را اندازه می‌گیرم.',54,NULL,NULL,'ja ich messe sie gleich',NULL,'[{"surface":"Ja","lemma":"ja","translation":"بله / آره","partOfSpeech":"interjection","suffix":","},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"messe","lemma":"messen","translation":"اندازه گرفتن","partOfSpeech":"verb"},{"surface":"sie","lemma":"sie","translation":"او / آن ها","partOfSpeech":"pronoun"},{"surface":"gleich","lemma":"gleich","translation":"همین الان","partOfSpeech":"adverb","suffix":"."}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_10=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_2,v_c_sara,5,'character','Rufst du vorher in der Praxis an?','قبلش به مطب زنگ می‌زنی؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Rufst","lemma":"anrufen","translation":"زنگ زدن / تماس گرفتن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"vorher","lemma":"vorher","translation":"قبلش / پیش از آن","partOfSpeech":"adverb"},{"surface":"in","lemma":"in","translation":"در / داخل","partOfSpeech":"preposition"},{"surface":"der","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Praxis","lemma":"Praxis","translation":"مطب","partOfSpeech":"noun"},{"surface":"an","lemma":"anrufen","translation":"زنگ زدن / تماس گرفتن","partOfSpeech":"verb","suffix":"?"}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_11=LAST_INSERT_ID();
