  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'In der Praxis anrufen','تماس با مطب','Mia übt, ihre anhaltenden Beschwerden am Telefon zu erklären und einen neuen Termin zu vereinbaren.','میا تمرین می‌کند نشانه‌های ادامه‌دارش را تلفنی توضیح دهد و وقت تازه‌ای بگیرد.','story','mia-sara-b1-health-routine',11,54,180,3,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"call-practice"}'); SET v_l_3=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_sara,1,'character','Was sagst du am Telefon?','پشت تلفن چه می‌گویی؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Was","lemma":"was","translation":"چی / چه","partOfSpeech":"pronoun"},{"surface":"sagst","lemma":"sagen","translation":"گفتن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"am","lemma":"an","translation":"در / در روز","partOfSpeech":"preposition"},{"surface":"Telefon","lemma":"Telefon","translation":"تلفن","partOfSpeech":"noun","suffix":"?"}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_13=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_mia,2,'learner','Ich sage, dass meine Beschwerden noch da sind.','می‌گویم که نشانه‌هایم هنوز وجود دارند.',54,NULL,NULL,'ich sage dass meine beschwerden noch da sind',NULL,'[{"surface":"Ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"sage","lemma":"sagen","translation":"گفتن","partOfSpeech":"verb","suffix":","},{"surface":"dass","lemma":"dass","translation":"که","partOfSpeech":"conjunction"},{"surface":"meine","lemma":"mein","translation":"مال من / من","partOfSpeech":"determiner"},{"surface":"Beschwerden","lemma":"Beschwerde","translation":"شکایت","partOfSpeech":"noun"},{"surface":"noch","lemma":"noch","translation":"هنوز","partOfSpeech":"adverb"},{"surface":"da","lemma":"da","translation":"آنجا","partOfSpeech":"adverb"},{"surface":"sind","lemma":"sein","translation":"بودن","partOfSpeech":"verb","suffix":"."}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_14=LAST_INSERT_ID();
