  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Der sichere nächste Schritt','گام بعدی مطمئن','Sara und Mia klären, wann Mia sofort Hilfe braucht und wann sie weiter ruhen kann.','سارا و میا روشن می‌کنند چه زمانی میا به کمک فوری نیاز دارد و چه زمانی می‌تواند به استراحت ادامه دهد.','story','mia-sara-b1-health-routine',12,54,180,4,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"safe-next-step"}'); SET v_l_4=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,1,'character','Und wenn du plötzlich Fieber bekommst?','اگر ناگهان تب کنی چه؟',54,NULL,NULL,NULL,NULL,'[{"surface":"Und","lemma":"und","translation":"و","partOfSpeech":"conjunction"},{"surface":"wenn","lemma":"wenn","translation":"اگر / وقتی","partOfSpeech":"conjunction"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"plötzlich","lemma":"plötzlich","translation":"ناگهان","partOfSpeech":"adverb"},{"surface":"Fieber","lemma":"Fieber","translation":"تب","partOfSpeech":"noun"},{"surface":"bekommst","lemma":"bekommen","translation":"گرفتن / دچار شدن","partOfSpeech":"verb","suffix":"?"}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_19=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,2,'learner','Dann warte ich nicht bis morgen.','آن‌وقت تا فردا صبر نمی‌کنم.',54,NULL,NULL,'dann warte ich nicht bis morgen',NULL,'[{"surface":"Dann","lemma":"dann","translation":"بعد / سپس","partOfSpeech":"adverb"},{"surface":"warte","lemma":"warten","translation":"منتظر ماندن / صبر کردن","partOfSpeech":"verb"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"nicht","lemma":"nicht","translation":"نه / نیست","partOfSpeech":"adverb"},{"surface":"bis","lemma":"bis","translation":"تا","partOfSpeech":"conjunction"},{"surface":"morgen","lemma":"morgen","translation":"فردا","partOfSpeech":"adverb","suffix":"."}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_20=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,3,'character','Genau, dann brauchst du sofort Hilfe.','دقیقاً، آن‌وقت فوراً به کمک نیاز داری.',54,NULL,NULL,NULL,NULL,'[{"surface":"Genau","lemma":"genau","translation":"دقیقا","partOfSpeech":"adverb","suffix":","},{"surface":"dann","lemma":"dann","translation":"بعد / سپس","partOfSpeech":"adverb"},{"surface":"brauchst","lemma":"brauchen","translation":"نیاز داشتن / لازم داشتن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"sofort","lemma":"sofort","translation":"فورا / همین الان","partOfSpeech":"adverb"},{"surface":"Hilfe","lemma":"Hilfe","translation":"کمک","partOfSpeech":"noun","suffix":"."}]','Bedingungen mit wenn und medizinische Schritte','با wenn شرط واقعی بیان می‌شود؛ در جملهٔ وابسته فعل در پایان می‌آید و جملهٔ اصلی اقدام بعدی را مشخص می‌کند.','{"focus":"wenn_health_followup","structures":["wenn clause","reported symptoms","passive with werden","temporal bis clause"]}','{"cefr":"B1","course":"de-fa","series":103}'); SET v_t_21=LAST_INSERT_ID();
