  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Das Handy am Abend','گوشی در شب','Mia erkennt, wie der Bildschirm ihren Schlaf stört, und entscheidet sich für eine frühere Handy-Pause.','میا متوجه می شود صفحه نمایش چطور خوابش را مختل می کند و تصمیم می گیرد گوشی را زودتر کنار بگذارد.','story','mia-sara-b1-health-routine',14,55,180,2,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"reduce-evening-screen"}'); SET v_l_2=LAST_INSERT_ID();
