  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Ein fester Rhythmus','یک برنامه ثابت','Mia legt feste Schlaf- und Aufstehzeiten fest und macht daraus eine regelmäßige Gewohnheit.','میا زمان مشخصی برای خواب و بیدار شدن تعیین می کند و آن را به یک عادت منظم تبدیل می کند.','story','mia-sara-b1-health-routine',15,55,180,3,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"set-sleep-rhythm"}'); SET v_l_3=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_3,v_c_sara,1,'character','Wann willst du ins Bett gehen?','کی می خواهی به تخت بروی؟',55,NULL,NULL,NULL,NULL,'[{"surface":"Wann","lemma":"wann","translation":"کی / چه زمانی","partOfSpeech":"adverb"},{"surface":"willst","lemma":"wollen","translation":"خواستن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"ins","lemma":"in","translation":"در / داخل","partOfSpeech":"preposition"},{"surface":"Bett","lemma":"Bett","translation":"تخت","partOfSpeech":"noun"},{"surface":"gehen","lemma":"gehen","translation":"رفتن","partOfSpeech":"verb","suffix":"?"}]','Mit sollte über gesunde Gewohnheiten sprechen','با sollte توصیه یا تصمیم ملایم بیان می‌شود. قیدهای زمان و مقدار برنامهٔ خواب را دقیق‌تر می‌کنند.','{"focus":"sollte_sleep_routine","structures":["sollte recommendation","time expressions","separable aufstehen","damit purpose clause"]}','{"cefr":"B1","course":"de-fa","series":104}'); SET v_t_13=LAST_INSERT_ID();
