  INSERT INTO lessons(chapter_id,prompt_character_id,learner_character_id,title,title_translation,description,description_translation,lesson_type,storyline_key,storyline_order,difficulty,estimated_duration_sec,sort_order,status,metadata) VALUES(v_chapter,v_c_sara,v_c_mia,'Der neue Abendplan','برنامه تازه شب','Sara und Mia schließen den Gesundheitsbogen mit einer ruhigen Abendroutine und einem klaren persönlichen Plan ab.','سارا و میا مسیر سلامتی را با یک برنامه آرام شبانه و یک تصمیم شخصی روشن به پایان می رسانند.','story','mia-sara-b1-health-routine',16,55,180,4,'validated','{"relationship":"friends","context":"health-routine","cefr":"B1","storyArc":"commit-evening-plan"}'); SET v_l_4=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,1,'character','Was hilft dir vor dem Schlafen?','پیش از خواب چه چیزی به تو کمک می کند؟',55,NULL,NULL,NULL,NULL,'[{"surface":"Was","lemma":"was","translation":"چی / چه","partOfSpeech":"pronoun"},{"surface":"hilft","lemma":"helfen","translation":"کمک کردن","partOfSpeech":"verb"},{"surface":"dir","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"vor","lemma":"vor","translation":"از / جلوی","partOfSpeech":"preposition"},{"surface":"dem","lemma":"der","translation":"حرف تعریف","partOfSpeech":"article"},{"surface":"Schlafen","lemma":"schlafen","translation":"خوابیدن","partOfSpeech":"verb","suffix":"?"}]','Mit sollte über gesunde Gewohnheiten sprechen','با sollte توصیه یا تصمیم ملایم بیان می‌شود. قیدهای زمان و مقدار برنامهٔ خواب را دقیق‌تر می‌کنند.','{"focus":"sollte_sleep_routine","structures":["sollte recommendation","time expressions","separable aufstehen","damit purpose clause"]}','{"cefr":"B1","course":"de-fa","series":104}'); SET v_t_19=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,2,'learner','Etwas Ruhe und ein bisschen Wasser.','کمی آرامش و کمی آب.',55,NULL,NULL,'etwas ruhe und ein bisschen wasser',NULL,'[{"surface":"Etwas","lemma":"etwas","translation":"چیزی / یک چیزی","partOfSpeech":"pronoun"},{"surface":"Ruhe","lemma":"Ruhe","translation":"آرامش / سکوت","partOfSpeech":"noun"},{"surface":"und","lemma":"und","translation":"و","partOfSpeech":"conjunction"},{"surface":"ein","lemma":"ein","translation":"یک / حرف تعریف نامعین","partOfSpeech":"article"},{"surface":"bisschen","lemma":"bisschen","translation":"کمی","partOfSpeech":"noun"},{"surface":"Wasser","lemma":"Wasser","translation":"آب","partOfSpeech":"noun","suffix":"."}]','Mit sollte über gesunde Gewohnheiten sprechen','با sollte توصیه یا تصمیم ملایم بیان می‌شود. قیدهای زمان و مقدار برنامهٔ خواب را دقیق‌تر می‌کنند.','{"focus":"sollte_sleep_routine","structures":["sollte recommendation","time expressions","separable aufstehen","damit purpose clause"]}','{"cefr":"B1","course":"de-fa","series":104}'); SET v_t_20=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,3,'character','Willst du weniger auf dein Handy sehen?','می خواهی کمتر به گوشی ات نگاه کنی؟',55,NULL,NULL,NULL,NULL,'[{"surface":"Willst","lemma":"wollen","translation":"خواستن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"weniger","lemma":"weniger","translation":"کمتر","partOfSpeech":"adverb"},{"surface":"auf","lemma":"auf","translation":"روی / برای","partOfSpeech":"preposition"},{"surface":"dein","lemma":"dein","translation":"مال تو / تو","partOfSpeech":"determiner"},{"surface":"Handy","lemma":"Handy","translation":"گوشی","partOfSpeech":"noun"},{"surface":"sehen","lemma":"sehen","translation":"دیدن","partOfSpeech":"verb","suffix":"?"}]','Mit sollte über gesunde Gewohnheiten sprechen','با sollte توصیه یا تصمیم ملایم بیان می‌شود. قیدهای زمان و مقدار برنامهٔ خواب را دقیق‌تر می‌کنند.','{"focus":"sollte_sleep_routine","structures":["sollte recommendation","time expressions","separable aufstehen","damit purpose clause"]}','{"cefr":"B1","course":"de-fa","series":104}'); SET v_t_21=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_mia,4,'learner','Ja, damit ich besser schlafen kann.','بله، تا بتوانم بهتر بخوابم.',55,NULL,NULL,'ja damit ich besser schlafen kann',NULL,'[{"surface":"Ja","lemma":"ja","translation":"بله / آره","partOfSpeech":"interjection","suffix":","},{"surface":"damit","lemma":"damit","translation":"تا / برای اینکه","partOfSpeech":"conjunction"},{"surface":"ich","lemma":"ich","translation":"من","partOfSpeech":"pronoun"},{"surface":"besser","lemma":"besser","translation":"بهتر","partOfSpeech":"adverb"},{"surface":"schlafen","lemma":"schlafen","translation":"خوابیدن","partOfSpeech":"verb"},{"surface":"kann","lemma":"können","translation":"توانستن / بتوان","partOfSpeech":"verb","suffix":"."}]','Mit sollte über gesunde Gewohnheiten sprechen','با sollte توصیه یا تصمیم ملایم بیان می‌شود. قیدهای زمان و مقدار برنامهٔ خواب را دقیق‌تر می‌کنند.','{"focus":"sollte_sleep_routine","structures":["sollte recommendation","time expressions","separable aufstehen","damit purpose clause"]}','{"cefr":"B1","course":"de-fa","series":104}'); SET v_t_22=LAST_INSERT_ID();
  INSERT INTO turns(lesson_id,character_id,sort_order,role,text,translation,difficulty,audio_url,audio_duration_ms,speech_target,speech_alternatives,tokens,grammar_title,grammar_note,grammar_data,metadata) VALUES(v_l_4,v_c_sara,5,'character','Dann bist du morgen vielleicht weniger müde.','پس شاید فردا کمتر خسته باشی.',55,NULL,NULL,NULL,NULL,'[{"surface":"Dann","lemma":"dann","translation":"بعد / سپس","partOfSpeech":"adverb"},{"surface":"bist","lemma":"sein","translation":"بودن","partOfSpeech":"verb"},{"surface":"du","lemma":"du","translation":"تو","partOfSpeech":"pronoun"},{"surface":"morgen","lemma":"morgen","translation":"فردا","partOfSpeech":"adverb"},{"surface":"vielleicht","lemma":"vielleicht","translation":"شاید","partOfSpeech":"adverb"},{"surface":"weniger","lemma":"weniger","translation":"کمتر","partOfSpeech":"adverb"},{"surface":"müde","lemma":"müde","translation":"خسته","partOfSpeech":"adjective","suffix":"."}]','Mit sollte über gesunde Gewohnheiten sprechen','با sollte توصیه یا تصمیم ملایم بیان می‌شود. قیدهای زمان و مقدار برنامهٔ خواب را دقیق‌تر می‌کنند.','{"focus":"sollte_sleep_routine","structures":["sollte recommendation","time expressions","separable aufstehen","damit purpose clause"]}','{"cefr":"B1","course":"de-fa","series":104}'); SET v_t_23=LAST_INSERT_ID();
